Lemma stack_at_agree2 : forall (M M' : word -> option byte) V es b capb, 0 <= V -> V + ENC_SIZE <= 2 ^ 64 ->
  L5C.agree_on M M' (V + O_STACK) 8 -> L5C.agree_on M M' (V + O_STACK + 16) 8 -> PMSA.u64 L M' (V + O_STACK + 8) (b + 32 * depth es) ->
